import { createFileRoute, Navigate } from '@tanstack/react-router';

import { Step2Prompt } from '@/routes/_authenticated/start/-components/steps/Step2Prompt';
import { useStartFlow } from '@/routes/_authenticated/start/-startFlow.context';

export const Route = createFileRoute('/_authenticated/start/prompt/')({
  component: RouteComponent
});

function RouteComponent() {
  const {
    selectedDraftTemplate,
    setPrompt,
    templateName,
    selectedPromptProfile,
    promptState,
    setPromptMode,
    setIdeaText,
    setAiAnswers
  } = useStartFlow();

  if (!selectedDraftTemplate) {
    return <Navigate to="/start/template" replace />;
  }

  return (
    <Step2Prompt
      onPromptChange={setPrompt}
      templateName={templateName}
      promptProfile={selectedPromptProfile}
      activeTab={promptState.activeTab}
      onActiveTabChange={setPromptMode}
      ideaText={promptState.ideaText}
      onIdeaTextChange={setIdeaText}
      aiAnswers={promptState.aiAnswers}
      onAiAnswersChange={setAiAnswers}
    />
  );
}
