import styled from '@emotion/styled';
import {
  Button,
  SegmentedControlItem,
  SegmentedControlRoot,
  TextField,
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger
} from '@bichon/ds';
import { Flex, useToast } from '@docs-front/ui';
import { Info, WandSparkles } from 'lucide-react';
import { useEffect, useRef, useState, type ChangeEvent } from 'react';

import { generateAI } from '@/api/ai';
import {
  StyledInfoBanner,
  StyledStepHeader,
  StyledStepSubtitle,
  StyledTemplateName,
  StyledToggleWrapper
} from '@/routes/_authenticated/f/prompt/-prompt.style';
import {
  StyledAIButtonWrapper,
  StyledAIFieldWrapper,
  StyledFieldBlock,
  StyledFieldError,
  StyledFieldLabel,
  StyledFieldMetaRow
} from '@/routes/_authenticated/f/prompt/-components/AIReviewerMode/AIReviewerMode.style';
import type { DraftPromptProfile } from '@/routes/_authenticated/start/-components/steps/draftTemplateProfile';
import type { StartPromptMode } from '@/routes/_authenticated/start/-startFlow.types';
import {
  getStartAIQuestions,
  type StartAIQuestion
} from '@/routes/_authenticated/start/-components/steps/Step2Prompt.utils';
import { MAX_AI_PROMPT_LENGTH } from '@/schema/api/ai';
import {
  getTextLength,
  MAX_IDEA_MODE_LENGTH,
  MAX_DETAIL_INPUT_PAGE_LENGTH
} from '@/schema/main/detailInput';

const StyledPromptLayout = styled.div`
  display: flex;
  flex-direction: column;
  gap: 24px;
  width: 100%;
`;

const StyledQuestionContent = styled.div`
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
`;

const StyledAITextField = styled(TextField)`
  textarea {
    padding-right: 132px;
    padding-bottom: 64px;
  }
`;

const AI_MIN_PROMPT_LENGTH = 7;
const AI_MIN_PROMPT_WARNING_TEXT = `${AI_MIN_PROMPT_LENGTH}글자 이상 입력해주세요.`;
const AI_LOW_INFORMATION_TOOLTIP =
  '의미 있는 문장으로 입력해주세요. 같은 글자 반복 입력은 AI 심사가 어렵습니다.';
const AI_LOW_INFO_MIN_CHECK_LENGTH = 30;
const AI_LOW_INFO_REPEAT_RATIO = 0.85;
const isBlankText = (value?: string | null) =>
  value == null || value.trim().length === 0;

const isLowInformationInput = (value: string) => {
  const normalized = Array.from(value.replace(/\s+/g, ''));
  if (normalized.length < AI_LOW_INFO_MIN_CHECK_LENGTH) return false;

  const frequencies = new Map<string, number>();
  let maxFrequency = 0;

  normalized.forEach((char) => {
    const next = (frequencies.get(char) ?? 0) + 1;
    frequencies.set(char, next);
    if (next > maxFrequency) {
      maxFrequency = next;
    }
  });

  return maxFrequency / normalized.length >= AI_LOW_INFO_REPEAT_RATIO;
};

type AIBlockedReason =
  | 'NONE'
  | 'PROMPT_TOO_LONG'
  | 'LOW_INFORMATION'
  | 'TOO_SHORT';

const getBlockedReason = ({
  currentValue,
  promptLength
}: {
  currentValue: string;
  promptLength: number;
}): AIBlockedReason => {
  if (promptLength > MAX_AI_PROMPT_LENGTH) return 'PROMPT_TOO_LONG';
  if (promptLength < AI_MIN_PROMPT_LENGTH) return 'TOO_SHORT';
  if (currentValue.trim().length > 0 && isLowInformationInput(currentValue)) {
    return 'LOW_INFORMATION';
  }
  return 'NONE';
};

const getBlockedTooltip = (reason: AIBlockedReason, promptLength: number) => {
  if (reason === 'PROMPT_TOO_LONG') {
    return `AI 프롬프트가 너무 깁니다. ${promptLength}/${MAX_AI_PROMPT_LENGTH}자 (공백 포함)`;
  }
  if (reason === 'LOW_INFORMATION') return AI_LOW_INFORMATION_TOOLTIP;
  if (reason === 'TOO_SHORT') return AI_MIN_PROMPT_WARNING_TEXT;
  return '쉽고 빠르게 프롬프트 작성';
};

const buildAIPrompt = ({
  questionKey,
  currentValue,
  answers,
  questions
}: {
  questionKey: string;
  currentValue: string;
  answers: Record<string, string>;
  questions: StartAIQuestion[];
}) => {
  const questionIndex = questions.findIndex(({ key }) => key === questionKey);
  const currentQuestion = questions[questionIndex];
  const previousContext =
    questionIndex <= 0
      ? []
      : questions
          .slice(0, questionIndex)
          .map(({ key, label }) => {
            const value = answers[key];
            if (isBlankText(value)) return null;
            return `${label}\n${value.trim()}`;
          })
          .filter((value): value is string => value !== null);
  const trimmedCurrentValue = currentValue.trim();

  if (!currentQuestion) return trimmedCurrentValue;

  if (previousContext.length === 0) {
    return trimmedCurrentValue;
  }

  if (trimmedCurrentValue.length === 0) {
    return [
      '[작성 대상 문항]',
      currentQuestion.label,
      '[이전 입력 정보]',
      previousContext.join('\n\n'),
      '[요청]',
      '위 정보를 바탕으로 작성 대상 문항을 구체적으로 작성해주세요.'
    ].join('\n\n');
  }

  return [
    '[현재 입력]',
    `${currentQuestion.label}\n${trimmedCurrentValue}`,
    '[이전 입력 정보]',
    previousContext.join('\n\n')
  ].join('\n\n');
};

interface Step2Props {
  onPromptChange: (value: string) => void;
  templateName: string;
  promptProfile?: DraftPromptProfile;
  activeTab: StartPromptMode;
  onActiveTabChange: (mode: StartPromptMode) => void;
  ideaText: string;
  onIdeaTextChange: (value: string) => void;
  aiAnswers: Record<string, string>;
  onAiAnswersChange: (answers: Record<string, string>) => void;
}

const getInputValue = (
  eventOrValue: string | ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
) =>
  typeof eventOrValue === 'string' ? eventOrValue : eventOrValue.target.value;

export function Step2Prompt({
  onPromptChange,
  templateName,
  promptProfile = 'business_plan',
  activeTab,
  onActiveTabChange,
  ideaText,
  onIdeaTextChange,
  aiAnswers,
  onAiAnswersChange
}: Step2Props) {
  const toast = useToast();
  const [loadingFields, setLoadingFields] = useState<Set<string>>(new Set());
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const abortControllersRef = useRef<Map<string, AbortController>>(new Map());
  const aiAnswersRef = useRef(aiAnswers);

  const isRndTemplate = promptProfile === 'rnd_plan';
  const isEveryoneStartupTemplate = promptProfile === 'everyone_startup';
  const aiQuestions = getStartAIQuestions(promptProfile);
  useEffect(() => {
    aiAnswersRef.current = aiAnswers;
  }, [aiAnswers]);

  useEffect(() => {
    const controllers = abortControllersRef.current;
    return () => {
      controllers.forEach((controller) => controller.abort());
      controllers.clear();
    };
  }, []);

  const clearFieldError = (questionKey: string) => {
    setFieldErrors((prev) => {
      if (!prev[questionKey]) return prev;
      const next = { ...prev };
      delete next[questionKey];
      return next;
    });
  };

  const handleAiAnswer = (questionKey: string, value: string) => {
    const nextAnswers = {
      ...aiAnswersRef.current,
      [questionKey]: value
    };
    aiAnswersRef.current = nextAnswers;
    onAiAnswersChange(nextAnswers);

    const nextPrompt = buildAIPrompt({
      questionKey,
      currentValue: value,
      answers: nextAnswers,
      questions: aiQuestions
    });

    if (
      getTextLength(nextPrompt) >= AI_MIN_PROMPT_LENGTH &&
      fieldErrors[questionKey] === AI_MIN_PROMPT_WARNING_TEXT
    ) {
      clearFieldError(questionKey);
    }
  };

  const handleCancel = (questionKey: string) => {
    const controller = abortControllersRef.current.get(questionKey);
    if (controller) controller.abort();
  };

  const handleAiJudge = async (question: StartAIQuestion) => {
    const currentValue = aiAnswersRef.current[question.key] ?? '';
    const aiPrompt = buildAIPrompt({
      questionKey: question.key,
      currentValue,
      answers: aiAnswersRef.current,
      questions: aiQuestions
    });
    const promptLength = getTextLength(aiPrompt);
    const reason = getBlockedReason({ currentValue, promptLength });

    if (reason !== 'NONE') {
      if (reason === 'TOO_SHORT') {
        setFieldErrors((prev) => ({
          ...prev,
          [question.key]: AI_MIN_PROMPT_WARNING_TEXT
        }));
      } else {
        toast.open({
          content: getBlockedTooltip(reason, promptLength),
          duration: 2000
        });
      }
      return;
    }

    clearFieldError(question.key);

    const existing = abortControllersRef.current.get(question.key);
    if (existing) existing.abort();

    const controller = new AbortController();
    abortControllersRef.current.set(question.key, controller);
    setLoadingFields((prev) => new Set(prev).add(question.key));

    try {
      const response = await generateAI(
        question.type
          ? { prompt: aiPrompt, type: question.type }
          : { prompt: aiPrompt },
        controller.signal
      );

      const nextAnswers = {
        ...aiAnswersRef.current,
        [question.key]: response.text
      };
      aiAnswersRef.current = nextAnswers;
      onAiAnswersChange(nextAnswers);
      clearFieldError(question.key);
      toast.open({
        content: 'AI 심사가 완료되었습니다.',
        duration: 2000
      });
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        toast.open({ content: '요청이 취소되었습니다.', duration: 2000 });
        return;
      }

      let errorMessage = 'AI 생성 중 오류가 발생했습니다.';

      if (error instanceof Error) {
        if (error.name === 'TimeoutError') {
          errorMessage = '요청 시간이 초과되었습니다. 다시 시도해주세요.';
        } else if (
          error.message.includes('Failed to fetch') ||
          error.message.includes('NetworkError')
        ) {
          errorMessage = '네트워크 오류가 발생했습니다. 다시 시도해주세요.';
        } else {
          errorMessage = error.message;
        }
      }

      toast.open({
        content: errorMessage,
        duration: 3000
      });
    } finally {
      abortControllersRef.current.delete(question.key);
      setLoadingFields((prev) => {
        const next = new Set(prev);
        next.delete(question.key);
        return next;
      });
    }
  };

  useEffect(() => {
    if (activeTab !== 'idea') return;
    onPromptChange(ideaText);
  }, [activeTab, ideaText, onPromptChange]);

  useEffect(() => {
    if (activeTab !== 'aiReviewer') return;

    const entries = aiQuestions
      .filter((question) => aiAnswers[question.key]?.trim())
      .map((question) => `${question.label}\n${aiAnswers[question.key]}`);

    onPromptChange(entries.join('\n\n'));
  }, [activeTab, aiAnswers, aiQuestions, onPromptChange]);

  return (
    <StyledPromptLayout>
      <StyledStepHeader>
        <StyledTemplateName>&apos;{templateName}&apos;</StyledTemplateName>
        <StyledStepSubtitle>
          문서 작성을 위한 프롬프트를 입력해주세요
        </StyledStepSubtitle>
      </StyledStepHeader>

      <StyledInfoBanner>
        <Info size={16} />
        <span>
          사업아이템 설명을 자유롭게 입력하거나, AI 심사역과 함께 고도화하는
          단계입니다. 단계를 건너뛸 수 있습니다.
        </span>
      </StyledInfoBanner>

      <StyledToggleWrapper>
        <SegmentedControlRoot
          value={activeTab}
          onValueChange={(value) => {
            if (value) onActiveTabChange(value as StartPromptMode);
          }}
        >
          <SegmentedControlItem value="idea">
            아이디어 모드
          </SegmentedControlItem>
          <SegmentedControlItem value="aiReviewer">
            AI 심사역과 함께
          </SegmentedControlItem>
        </SegmentedControlRoot>
      </StyledToggleWrapper>

      {activeTab === 'idea' ? (
        <TextField
          multiline
          minRows={12}
          maxLength={MAX_IDEA_MODE_LENGTH}
          width="100%"
          value={ideaText}
          placeholder={
            isRndTemplate
              ? "자유롭게 아이템 내용을 입력할 수 있습니다.\n\n구체적인 내용 없이 간략하게만 입력하면 AI가 부정확한 내용을 생성할 수 있습니다.\n'AI 심사역과 함께' 기능을 활용하여 항목별로 자세히 입력하면 보다 정확한 결과물을 얻을 수 있습니다."
              : isEveryoneStartupTemplate
              ? "아이디어 한 줄 소개, 시작하게 된 배경, 해결하려는 문제, 실현 계획과 멘토에게 묻고 싶은 내용을 자유롭게 적어주세요.\n\n항목별로 정리하고 싶다면 'AI 심사역과 함께' 기능을 활용해보세요."
              : "자유롭게 아이템 내용을 입력할 수 있습니다. 프롬프트 작성이 막막하다면 'AI 심사역과 함께' 진행해보세요."
          }
          onChange={(eventOrValue) => {
            onIdeaTextChange(
              getInputValue(
                eventOrValue as
                  | string
                  | ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
              )
            );
          }}
        />
      ) : (
        <Flex direction="column" gap={0} width="100%">
          {aiQuestions.map((question) => {
            const renderedPrompt = buildAIPrompt({
              questionKey: question.key,
              currentValue: aiAnswers[question.key] ?? '',
              answers: aiAnswers,
              questions: aiQuestions
            });
            const promptLength = getTextLength(renderedPrompt);
            const reason = getBlockedReason({
              currentValue: aiAnswers[question.key] ?? '',
              promptLength
            });

            return (
              <StyledFieldBlock key={question.key}>
                <StyledQuestionContent>
                  <StyledFieldLabel>{question.label}</StyledFieldLabel>
                  <StyledAIFieldWrapper>
                    <StyledAITextField
                      multiline
                      minRows={5}
                      maxLength={MAX_DETAIL_INPUT_PAGE_LENGTH}
                      width="100%"
                      value={aiAnswers[question.key] || ''}
                      placeholder={question.placeholder}
                      onChange={(eventOrValue) => {
                        handleAiAnswer(
                          question.key,
                          getInputValue(
                            eventOrValue as
                              | string
                              | ChangeEvent<
                                  HTMLInputElement | HTMLTextAreaElement
                                >
                          )
                        );
                      }}
                    />
                    <StyledAIButtonWrapper>
                      <TooltipProvider>
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <span style={{ display: 'inline-flex' }}>
                              <Button
                                type="button"
                                variant="outlined"
                                size="medium"
                                onClick={() =>
                                  loadingFields.has(question.key)
                                    ? handleCancel(question.key)
                                    : handleAiJudge(question)
                                }
                                onMouseDown={(event) => {
                                  event.preventDefault();
                                  event.stopPropagation();
                                }}
                              >
                                <WandSparkles size={14} />
                                {loadingFields.has(question.key)
                                  ? '분석 중...'
                                  : 'AI 심사역'}
                              </Button>
                            </span>
                          </TooltipTrigger>
                          <TooltipContent side="bottom">
                            {loadingFields.has(question.key)
                              ? '대답 생성 중지'
                              : getBlockedTooltip(reason, promptLength)}
                          </TooltipContent>
                        </Tooltip>
                      </TooltipProvider>
                    </StyledAIButtonWrapper>
                  </StyledAIFieldWrapper>
                  {fieldErrors[question.key] && (
                    <StyledFieldMetaRow>
                      <StyledFieldError>
                        {fieldErrors[question.key]}
                      </StyledFieldError>
                    </StyledFieldMetaRow>
                  )}
                </StyledQuestionContent>
              </StyledFieldBlock>
            );
          })}
        </Flex>
      )}
    </StyledPromptLayout>
  );
}
